// OUTPOST-native dialogs replace browser prompt/confirm chrome.
function outpostDialog({title='OUTPOST',message='',value='',multiline=false,confirmOnly=false,danger=false,placeholder=''}={}){
 return new Promise(resolve=>{
  const overlay=document.createElement('div');overlay.className='outpost-dialog-backdrop';
  const panel=document.createElement('section');panel.className='outpost-dialog';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');
  const field=confirmOnly?'':(multiline?'<textarea class="outpost-dialog-input" rows="5"></textarea>':'<input class="outpost-dialog-input" type="text">');
  panel.innerHTML='<div class="outpost-dialog-kicker">OUTPOST · LOCAL ACTION</div><h3>'+esc(title)+'</h3>'+(message?'<p>'+esc(message)+'</p>':'')+field+'<div class="outpost-dialog-actions"><button type="button" class="secondary dialog-cancel">Cancel</button><button type="button" class="'+(danger?'dialog-danger':'primary')+' dialog-accept">'+(confirmOnly?'Continue':'Save')+'</button></div>';
  overlay.append(panel);document.body.append(overlay);
  const input=panel.querySelector('.outpost-dialog-input');if(input){input.value=value;input.placeholder=placeholder;}
  const finish=result=>{overlay.remove();resolve(result)};
  panel.querySelector('.dialog-cancel').onclick=()=>finish(null);
  panel.querySelector('.dialog-accept').onclick=()=>finish(confirmOnly?true:input.value);
  overlay.addEventListener('click',e=>{if(e.target===overlay)finish(null)});
  panel.addEventListener('keydown',e=>{if(e.key==='Escape')finish(null);if(e.key==='Enter'&&!multiline&&!confirmOnly){e.preventDefault();finish(input.value)}});
  if(input)input.focus();
 });
}


function outpostFileChooser({title='Choose a file',accept='',inputId=''}={}){
 return new Promise(resolve=>{
  const overlay=document.createElement('div');overlay.className='outpost-dialog-backdrop outpost-file-backdrop';
  const panel=document.createElement('section');panel.className='outpost-dialog outpost-file-dialog';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');
  panel.innerHTML='<div class="outpost-dialog-kicker">OUTPOST · FILE SELECTOR</div><h3>'+esc(title)+'</h3><p class="outpost-file-hint">Browse folders already configured in OUTPOST, or choose a file elsewhere on this device.</p><div class="outpost-file-toolbar"><button type="button" class="secondary" data-file-up disabled>← Back</button><div class="outpost-file-path">Configured folders</div></div><input class="outpost-file-search" type="search" placeholder="Search files and folders…"><div class="outpost-file-list"><p class="muted">Loading folders…</p></div><div class="outpost-file-actions"><button type="button" class="secondary" data-file-device>Browse device…</button><span class="outpost-file-spacer"></span><button type="button" class="secondary" data-file-cancel>Cancel</button></div>';
  overlay.append(panel);document.body.append(overlay);
  let current='',parentPath='',entries=[],closed=false;
  const finish=file=>{if(closed)return;closed=true;overlay.remove();resolve(file||null)};
  const list=panel.querySelector('.outpost-file-list'),pathLabel=panel.querySelector('.outpost-file-path'),up=panel.querySelector('[data-file-up]'),search=panel.querySelector('.outpost-file-search');
  const matches=name=>{if(!accept)return true;const rules=accept.split(',').map(x=>x.trim().toLowerCase()).filter(Boolean);return rules.some(rule=>rule.startsWith('.')?name.toLowerCase().endsWith(rule):rule==='application/zip'?name.toLowerCase().endsWith('.zip'):rule==='application/json'?name.toLowerCase().endsWith('.json'):rule==='text/plain'?/\.(txt|md|rst|csv|log)$/i.test(name):true)};
  const render=()=>{const q=search.value.trim().toLowerCase();const shown=entries.filter(x=>(!q||x.name.toLowerCase().includes(q))&&(x.directory||matches(x.name)));list.innerHTML=shown.map((x,i)=>'<button type="button" class="outpost-file-entry '+(x.directory?'is-folder':'is-file')+'" data-entry="'+i+'"><span class="outpost-file-entry-icon">'+(x.directory?'▰':'▤')+'</span><span class="outpost-file-entry-main"><b>'+esc(x.name)+'</b><small>'+(x.directory?'Folder':Number(x.size||0).toLocaleString()+' bytes')+'</small></span><span class="outpost-file-entry-arrow">'+(x.directory?'›':'Select')+'</span></button>').join('')||'<p class="muted outpost-file-empty">No matching files in this folder.</p>';};
  const load=async path=>{list.innerHTML='<p class="muted">Loading…</p>';try{const d=await api('fs/list?path='+encodeURIComponent(path));current=d.current||'';parentPath=d.parent||'';entries=d.entries||[];pathLabel.textContent=current||'Configured folders';up.disabled=!current;search.value='';render()}catch(e){list.innerHTML='<p class="ip-error">'+esc(e.message)+'</p>'}};
  panel.querySelector('[data-file-cancel]').onclick=()=>finish(null);
  overlay.addEventListener('click',e=>{if(e.target===overlay)finish(null)});
  panel.querySelector('[data-file-device]').onclick=()=>{const picker=document.createElement('input');picker.type='file';picker.accept=accept;picker.style.display='none';document.body.append(picker);picker.onchange=()=>{const file=picker.files?.[0]||null;picker.remove();finish(file)};picker.click();};
  up.onclick=()=>{if(current&&parentPath)load(parentPath);else if(current)load('')};
  search.oninput=render;
  list.onclick=async e=>{const b=e.target.closest('[data-entry]');if(!b)return;const x=entries[Number(b.dataset.entry)];if(!x)return;if(x.directory){load(x.path);return}if(!matches(x.name)){toast('That file type is not accepted here');return}b.disabled=true;b.querySelector('.outpost-file-entry-arrow').textContent='Opening…';try{const response=await fetch('/api/file/download?path='+encodeURIComponent(x.path));if(!response.ok){let d={};try{d=await response.json()}catch{}throw Error(d.error||'Could not read selected file')}const blob=await response.blob();finish(new File([blob],x.name,{type:blob.type||'application/octet-stream',lastModified:x.modified?x.modified*1000:Date.now()}))}catch(err){b.disabled=false;b.querySelector('.outpost-file-entry-arrow').textContent='Select';toast(err.message)}};
  panel.addEventListener('keydown',e=>{if(e.key==='Escape')finish(null)});
  load('');
 });
}

const $=s=>document.querySelector(s);
const api=async(path,opts={})=>{const r=await fetch('/api/'+path,{headers:{'Content-Type':'application/json'},...opts});let d;try{d=await r.json()}catch{throw Error('The local server returned an unreadable response')}if(!r.ok)throw Error(d.error||'Request failed');return d};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const toast=m=>{const t=$('#toast');t.textContent=m;t.classList.add('show');clearTimeout(window.outpostToastTimer);window.outpostToastTimer=setTimeout(()=>t.classList.remove('show'),2600)};
const viewNames={overview:['Overview','Your systems, knowledge and files in one private workspace.'],archive:['File archive','Browse and inspect files in folders you selected.'],offline:['Offline library','Your local ZIM archives and reference packs.'],knowledge:['Knowledge search','Find answers across your indexed local material.'],notes:['Notes','Capture thoughts and keep them close.'],collections:['Collections','Organise useful links and references.'],security:['Security desk','Defensive research and safe local inspection.'],network:['IP toolbox','Offline IPv4 and IPv6 network calculations.'],settings:['Settings','Choose which folders OUTPOST can access.']};
function view(v,updateRoute=true){if(!viewNames[v])v='overview';document.querySelectorAll('.view').forEach(x=>x.classList.toggle('hidden',x.id!==v));document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===v));$('#heading').textContent=viewNames[v][0];$('#subheading').textContent=viewNames[v][1];document.querySelector('.main').scrollTo({top:0,behavior:'instant'});if(updateRoute&&location.hash!=='#'+v)history.pushState({outpostView:v},'','#'+v);if(v==='notes')loadNotes();if(v==='collections')loadCollections();if(v==='settings')loadSettings();if(v==='archive')loadFiles();if(v==='offline')loadOffline();if(v==='security')loadSecurity();if(v==='overview')loadOverview()}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>view(b.dataset.view)));
document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>view(b.dataset.go)));
async function refresh(){const s=await api('status');$('#stat-notes').textContent=s.counts.notes;$('#stat-docs').textContent=s.counts.documents;$('#stat-collections').textContent=s.counts.collections;$('#stat-bookmarks').textContent=s.counts.bookmarks;return s}
async function loadOverview(){try{const [m]=await Promise.all([api('modules'),refresh()]);$('#overview-modules').innerHTML=m.map(x=>'<article class="module-card"><div class="module-top"><b>'+esc(x.name)+'</b><span class="module-state '+esc(x.status)+'">'+esc(x.status)+'</span></div><p>'+esc(x.role)+'</p></article>').join('')}catch(e){toast(e.message)}}
async function loadNotes(){try{const a=await api('notes');$('#notes-list').innerHTML=a.map(n=>'<div class="item"><b>'+esc(n.title)+'</b><p>'+esc(n.body)+'</p><small>'+new Date(n.updated*1000).toLocaleString()+'</small><div class="action-row"><button class="secondary" onclick="editNote('+n.id+')">Edit</button><button class="secondary" onclick="deleteItem(\'notes\','+n.id+')">Delete</button></div></div>').join('')||'<p class="empty-state">No notes yet. Create your first one.</p>'}catch(e){toast(e.message)}}
async function loadCollections(){try{const [a,b]=await Promise.all([api('collections'),api('bookmarks')]);$('#collections-list').innerHTML=a.map(c=>'<div class="item"><b>'+esc(c.name)+'</b><p>'+esc(c.description)+'</p><div class="action-row"><button class="secondary" onclick="deleteItem(\'collections\','+c.id+')">Delete collection</button></div></div>').join('')||'<p class="empty-state">No collections yet.</p>';$('#bookmark-collection').innerHTML=a.map(c=>'<option value="'+c.id+'">'+esc(c.name)+'</option>').join('');$('#bookmarks-list').innerHTML=b.map(x=>'<div class="item"><b>'+esc(x.title)+'</b><p>'+esc(x.note)+'</p>'+(x.url?'<a href="'+esc(x.url)+'" target="_blank" rel="noopener noreferrer">'+esc(x.url)+'</a>':'')+'<small>'+esc(x.collection_name||'Unsorted')+'</small><button class="secondary" onclick="deleteItem(\'bookmarks\','+x.id+')">Delete</button></div>').join('')||'<p class="empty-state">No saved references yet.</p>'}catch(e){toast(e.message)}}
window.editNote=async id=>{try{const a=await api('notes');const n=a.find(x=>x.id===id);if(!n)return;const title=await outpostDialog({title:'Edit note title',value:n.title,placeholder:'Note title'});if(title===null)return;const body=await outpostDialog({title:'Edit note',message:'Update the note content.',value:n.body,multiline:true,placeholder:'Write your note…'});if(body===null)return;await api('notes/update',{method:'POST',body:JSON.stringify({id,title,body})});toast('Note updated');await loadNotes();await refresh()}catch(e){toast(e.message)}};
window.deleteItem=async(t,id)=>{if(!await outpostDialog({title:'Delete this item?',message:'This action cannot be undone.',confirmOnly:true,danger:true}))return;try{const r=await fetch('/api/'+t+'?id='+id,{method:'DELETE'});const d=await r.json();if(!r.ok)throw Error(d.error||'Delete failed');toast('Deleted');if(t==='notes')await loadNotes();if(t==='bookmarks'||t==='collections')await loadCollections();await refresh()}catch(e){toast(e.message)}};
$('#note-form').addEventListener('submit',async e=>{e.preventDefault();try{await api('notes',{method:'POST',body:JSON.stringify({title:$('#note-title').value,body:$('#note-body').value})});e.target.reset();toast('Note saved locally');await loadNotes();await refresh()}catch(x){toast(x.message)}});
$('#collection-form').addEventListener('submit',async e=>{e.preventDefault();try{await api('collections',{method:'POST',body:JSON.stringify({name:$('#collection-name').value})});e.target.reset();toast('Collection created');await loadCollections();await refresh()}catch(x){toast(x.message)}});
$('#bookmark-form').addEventListener('submit',async e=>{e.preventDefault();try{await api('bookmarks',{method:'POST',body:JSON.stringify({title:$('#bookmark-title').value,url:$('#bookmark-url').value,note:$('#bookmark-note').value,collection_id:Number($('#bookmark-collection').value)||null})});e.target.reset();toast('Reference saved');await loadCollections();await refresh()}catch(x){toast(x.message)}});
async function runSearch(input,result){const q=$(input).value.trim();if(!q)return;const target=$(result);target.innerHTML='<p class="muted">Searching your local library…</p>';try{const a=await api('search?q='+encodeURIComponent(q));target.innerHTML=(a||[]).map(x=>{const k=x.kind||'file';let act='';if(k==='file')act='<button class="secondary search-open-document" data-open-document="'+Number(x.id)+'">Open document ↗</button>';else if(k==='note')act='<button class="secondary search-open-note" data-open-note="'+Number(x.id)+'">Open note ↗</button>';else if(k==='bookmark'&&/^https?:\/\//i.test(x.url||''))act='<a class="secondary search-open-link" href="'+esc(x.url)+'" target="_blank" rel="noopener noreferrer">Open link ↗</a>';else act='<button class="secondary search-open-note" data-open-bookmark="'+Number(x.id)+'">Open reference ↗</button>';return '<article class="item search-result-item"><div class="search-result-copy"><div class="search-result-meta"><small>'+esc(k.toUpperCase())+'</small><small>'+esc(x.path||'')+'</small></div><b>'+esc(x.name)+'</b><p>'+esc(x.snippet||'')+'</p><div class="search-full-content" hidden>'+esc(x.content||x.snippet||'')+'</div></div>'+act+'</article>'}).join('')||'<p class="empty-state">No local matches. Try a shorter term, synonym, or add/index a folder in Settings.</p>';const terms=[...new Set((a||[]).flatMap(x=>x.suggested_terms||[]))];if(terms.length)target.insertAdjacentHTML('afterbegin','<p class="muted search-suggestion">Possible spelling: '+terms.map(esc).join(', ')+'</p>')}catch(e){target.innerHTML='<p class="ip-error">'+esc(e.message)+'</p>'}}
async function runKnowledgeAudit(){const box=$('#knowledge-audit-results');box.innerHTML='<p class="muted">Checking coverage…</p>';try{const r=await api('knowledge/audit');box.innerHTML='<b>'+Number(r.articles)+' articles checked · '+r.errors.length+' errors · '+r.warnings.length+' warnings</b>'+r.errors.map(x=>'<p class="ip-error">ERROR · '+esc(x)+'</p>').join('')+r.warnings.map(x=>'<p class="muted">REVIEW · '+esc(x)+'</p>').join('')+'<h4>Atlas checklist · '+(r.atlas_gaps||[]).length+' items still marked for review</h4>'+(r.atlas_gaps||[]).map(x=>'<p class="muted">• '+esc(x)+'</p>').join('')+'<p class="muted">'+esc(r.note)+'</p>'}catch(e){box.innerHTML='<p class="ip-error">'+esc(e.message)+'</p>'}}$('#knowledge-audit-run').onclick=runKnowledgeAudit;
$('#search-btn').onclick=()=>runSearch('#search-q','#search-results');$('#search-q').onkeydown=e=>{if(e.key==='Enter')runSearch('#search-q','#search-results')};
function renderDocumentMarkdown(source){
 const tick=String.fromCharCode(96);
 const inline=value=>esc(value).replace(new RegExp(tick+"([^"+tick+"]+)"+tick,"g"),"<code>$1</code>").replace(/\*\*([^*]+)\*\*/g,"<strong>$1</strong>").replace(/(^|[^*])\*([^*]+)\*/g,"$1<em>$2</em>").replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,"<a href=\"$2\" target=\"_blank\" rel=\"noopener noreferrer\">$1</a>");
 const lines=String(source||"").replace(/\r/g,"").split("\n");let out="",para=[],list="",inCode=false,code=[];
 const flushP=()=>{if(para.length){out+="<p>"+inline(para.join(" "))+"</p>";para=[]}};
 const flushL=()=>{if(list){out+="</"+list+">";list=""}};
 for(const line of lines){
  if(line.trim().startsWith(tick+tick+tick)){flushP();flushL();if(inCode){out+="<pre class=\"document-code\"><code>"+esc(code.join("\n"))+"</code></pre>";code=[];inCode=false}else inCode=true;continue}
  if(inCode){code.push(line);continue}
  const h=line.match(/^(#{1,6})\s+(.+)$/);
  if(h){flushP();flushL();const n=h[1].length;out+="<h"+n+">"+inline(h[2])+"</h"+n+">";continue}
  if(/^\s*([-*_])\1\1+\s*$/.test(line)){flushP();flushL();out+="<hr>";continue}
  const ul=line.match(/^\s*[-*+]\s+(.+)$/),ol=line.match(/^\s*\d+[.)]\s+(.+)$/);
  if(ul||ol){flushP();const kind=ul?"ul":"ol";if(list!==kind){flushL();list=kind;out+="<"+kind+">"}out+="<li>"+inline((ul||ol)[1])+"</li>";continue}
  if(!line.trim()){flushP();flushL();continue}
  flushL();para.push(line.trim());
 }
 if(inCode)out+="<pre class=\"document-code\"><code>"+esc(code.join("\n"))+"</code></pre>";
 flushP();flushL();return out||"<p class=\"muted\">This document is empty.</p>";
}
$('#search-results').addEventListener('click',async e=>{const doc=e.target.closest('[data-open-document]'),other=e.target.closest('[data-open-note],[data-open-bookmark]');if(!doc&&!other)return;const box=$('#search-reader');if(doc){const id=Number(doc.dataset.openDocument);if(!Number.isInteger(id)||id<1)return;doc.disabled=true;try{const d=await api('document?id='+id);box.hidden=false;box.innerHTML='<div class="document-reader-head"><div><div class="eyebrow">LOCAL DOCUMENT · FULL TEXT</div><h3>'+esc(d.name)+'</h3><p class="muted">'+esc(d.path)+' · '+Number(d.content.length).toLocaleString()+' characters</p></div><button type="button" class="secondary" id="close-search-reader">Close reader</button></div><div class="document-reader-actions"><button type="button" class="secondary" id="copy-search-document">Copy full text</button></div><article class="document-markdown">'+renderDocumentMarkdown(d.content)+'</article>';box.scrollIntoView({behavior:'smooth',block:'start'});$('#close-search-reader').onclick=()=>{box.hidden=true;box.innerHTML=''};$('#copy-search-document').onclick=()=>copyText(d.content)}catch(err){toast(err.message)}finally{doc.disabled=false}return}const id=Number(other.dataset.openNote||other.dataset.openBookmark);if(!Number.isInteger(id)||id<1)return;const k=other.hasAttribute('data-open-note')?'note':'bookmark',card=other.closest('.search-result-item'),title=card?.querySelector('.search-result-copy b')?.textContent||'Local item',content=card?.querySelector('.search-full-content')?.textContent||card?.querySelector('.search-result-copy p')?.textContent||'';box.hidden=false;box.innerHTML='<div class="document-reader-head"><div><div class="eyebrow">LOCAL '+k.toUpperCase()+'</div><h3>'+esc(title)+'</h3></div><button type="button" class="secondary" id="close-search-reader">Close</button></div><article class="document-markdown"><p>'+esc(content)+'</p></article>';box.scrollIntoView({behavior:'smooth',block:'start'});$('#close-search-reader').onclick=()=>{box.hidden=true;box.innerHTML=''}});
async function loadSettings(){try{const s=await api('status');$('#roots').value=(s.index_roots||[]).join('\n')}catch(e){toast(e.message)}}
$('#save-settings').onclick=async()=>{try{const a=$('#roots').value.split('\n').map(x=>x.trim()).filter(Boolean);const s=await api('settings',{method:'POST',body:JSON.stringify({index_roots:a})});$('#roots').value=s.index_roots.join('\n');toast('Folder settings saved')}catch(e){toast(e.message)}};
$('#index-now').onclick=async()=>{const b=$('#index-now');b.disabled=true;$('#settings-message').textContent='Indexing selected folders…';try{const a=await api('index',{method:'POST',body:'{}'});$('#settings-message').textContent='Indexed '+a.indexed+' files · skipped '+a.skipped;toast('Local index updated');await refresh()}catch(e){$('#settings-message').textContent=e.message;toast(e.message)}finally{b.disabled=false}};
let lastSettingsIndexResult='';
$('#copy-settings-result').onclick=()=>{if(lastSettingsIndexResult)copyText(lastSettingsIndexResult)};
$('#index-now').addEventListener('click',()=>{});
const originalSettingsIndexHandler=$('#index-now').onclick;
$('#index-now').onclick=async()=>{const b=$('#index-now');b.disabled=true;$('#copy-settings-result').disabled=true;$('#settings-message').textContent='Indexing selected folders…';try{const a=await api('index',{method:'POST',body:'{}'});lastSettingsIndexResult='Indexed '+a.indexed+' files · skipped '+a.skipped+(a.removed?' · removed '+a.removed+' stale entries':'')+'\nRoots: '+(a.roots||[]).join('\n');$('#settings-message').textContent=lastSettingsIndexResult;$('#copy-settings-result').disabled=false;toast('Local index updated');await refresh()}catch(e){$('#settings-message').textContent=e.message;lastSettingsIndexResult=e.message;$('#copy-settings-result').disabled=false;toast(e.message)}finally{b.disabled=false}};
$('#reset-index-settings').onclick=async()=>{const ok=await outpostDialog({title:'Reset folders and index?',message:'This clears configured index folders and rebuilds the local file index using OUTPOST’s built-in knowledge only. It does NOT delete files, notes, collections, bookmarks, ZIM archives or other personal data.',confirmOnly:true});if(!ok)return;const b=$('#reset-index-settings');b.disabled=true;$('#settings-message').textContent='Resetting folder settings and rebuilding index…';$('#copy-settings-result').disabled=true;try{await api('settings',{method:'POST',body:JSON.stringify({index_roots:[]})});$('#roots').value='';const a=await api('index',{method:'POST',body:'{}'});lastSettingsIndexResult='Reset complete. Indexed '+a.indexed+' built-in files · skipped '+a.skipped+(a.removed?' · removed '+a.removed+' stale entries':'')+'\nRoots: '+(a.roots||[]).join('\n');$('#settings-message').textContent=lastSettingsIndexResult;$('#copy-settings-result').disabled=false;toast('Folder settings and index reset');await refresh()}catch(e){$('#settings-message').textContent='Reset incomplete: '+e.message;lastSettingsIndexResult='Reset incomplete: '+e.message;$('#copy-settings-result').disabled=false;toast(e.message)}finally{b.disabled=false}};
$('#export-backup').onclick=async()=>{try{const data=await api('export');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='outpost-backup-'+new Date().toISOString().slice(0,10)+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported')}catch(e){toast(e.message)}};
$('#reset-outpost-full').onclick=async()=>{const first=await outpostDialog({title:'FULL OUTPOST RESET',message:'PERMANENT ACTION. This removes all OUTPOST database records (notes, collections, bookmarks and indexes), folder settings, imported knowledge packs, Wikipedia database and images, ZIM files stored inside OUTPOST, and the generated Kiwix reader. It does NOT delete files in external folders such as Downloads/Documents, your Termux packages, or OUTPOST source code. The existing JSON backup only exports notes, collections and bookmarks; it does not back up large libraries or imported files. Export records backup now and separately copy anything else you want to keep.',confirmOnly:true,danger:true});if(!first)return;const phrase=await outpostDialog({title:'Confirm permanent reset',message:'To continue, type RESET OUTPOST exactly. This cannot be undone.',placeholder:'Type RESET OUTPOST'});if(phrase!=='RESET OUTPOST'){toast('Full reset cancelled');return}const b=$('#reset-outpost-full');b.disabled=true;try{const result=await api('reset/full',{method:'POST',body:'{}'});toast(result.message||'OUTPOST reset complete');$('#roots').value='';lastSettingsIndexResult='Full OUTPOST reset complete.';$('#settings-message').textContent=lastSettingsIndexResult;$('#copy-settings-result').disabled=false;await refresh();await loadNotes();await loadCollections();await loadSettings()}catch(e){toast(e.message);$('#settings-message').textContent=e.message}finally{b.disabled=false}};
$('#import-backup').onclick=async()=>{const f=await outpostFileChooser({title:'Choose OUTPOST backup',accept:'.json,application/json'});if(!f)return;try{if(f.size>5_000_000)throw Error('Backup exceeds the 5 MB import limit');const data=JSON.parse(await f.text());if(!await outpostDialog({title:'Import backup?',message:'Existing data will be kept; backup records will be added.',confirmOnly:true}))return;await api('import',{method:'POST',body:JSON.stringify(data)});toast('Backup imported');await refresh();await loadNotes();await loadCollections()}catch(x){toast(x.message)}};
const ipHistoryKey='outpost.ip.history.v1';
function readIpHistory(){try{return JSON.parse(localStorage.getItem(ipHistoryKey)||'[]')}catch{return []}}
function renderIpHistory(){const items=readIpHistory();$('#ip-history').innerHTML=items.length?items.map((x,i)=>'<button type="button" class="ip-history-item" data-ip-history="'+i+'"><span>'+esc(x.input)+'</span><small>'+esc(x.network)+'</small></button>').join(''):'<p class="muted">Recent calculations will appear here on this device.</p>'}
async function copyText(text){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text)}else{const box=document.createElement('textarea');box.value=text;box.style.position='fixed';box.style.opacity='0';document.body.append(box);box.select();const ok=document.execCommand('copy');box.remove();if(!ok)throw Error('Clipboard unavailable')}toast('Copied to clipboard')}catch(e){toast('Could not copy: '+e.message)}}
function formatIpReport(rows){return ['OUTPOST · IP TOOLBOX','=====================','',...rows.map(x=>x[0]+': '+x[1])].join('\n')}
function showIpResult(d,input){
 const rows=[['IP version','IPv'+d.version],['Address',d.address+'/'+d.prefix],['Network',d.network+'/'+d.prefix],['Broadcast',d.broadcast||'Not applicable (IPv6)'],['Subnet mask',d.netmask],['Host mask',d.hostmask],['Total addresses',Number(d.total_addresses).toLocaleString()],['First address',d.first_host],['Last address',d.last_host],['Private',d.is_private?'Yes':'No'],['Global',d.is_global?'Yes':'No'],['Loopback',d.is_loopback?'Yes':'No'],['Link-local',d.is_link_local?'Yes':'No'],['Multicast',d.is_multicast?'Yes':'No']];
 window.outpostIpReport=rows;window.outpostIpInput=input;
 const range=d.version===4?'<div class="ip-range"><div class="ip-range-track"><span class="ip-range-network"></span><span class="ip-range-usable"></span><span class="ip-range-broadcast"></span></div><div class="ip-range-legend"><span>Network</span><span>Usable range</span><span>Broadcast</span></div></div>':'<div class="ip-range ipv6-range"><div class="ip-range-track"><span class="ip-range-usable"></span></div><p class="muted">IPv6 prefix range · '+esc(d.network)+' to '+esc(d.last_host)+'</p></div>';
 $('#ip-results').innerHTML='<div class="ip-result-head"><div><span class="eyebrow">CALCULATION COMPLETE</span><h3>'+esc(d.network)+'/'+d.prefix+'</h3><p class="muted">IPv'+d.version+' · '+esc(Number(d.total_addresses).toLocaleString())+' total addresses</p></div><button type="button" id="ip-copy-all" class="primary">Copy all info</button></div>'+range+'<div class="ip-result-grid">'+rows.map((x,i)=>'<div class="ip-result-row"><div><span>'+esc(x[0])+'</span><b>'+esc(x[1])+'</b></div><button type="button" class="ip-copy-one" data-ip-copy="'+i+'" aria-label="Copy '+esc(x[0])+'">Copy</button></div>').join('')+'</div>';
 const hist=readIpHistory().filter(x=>x.input!==input);hist.unshift({input,network:d.network+'/'+d.prefix});localStorage.setItem(ipHistoryKey,JSON.stringify(hist.slice(0,8)));renderIpHistory();
}
$('#ip-form').addEventListener('submit',async e=>{e.preventDefault();const input=$('#ip-input').value.trim();try{const d=await api('ip/calculate',{method:'POST',body:JSON.stringify({address:input})});showIpResult(d,input)}catch(x){$('#ip-results').innerHTML='<div class="ip-error">'+esc(x.message)+'</div>'}});
$('#ip-results').addEventListener('click',e=>{const all=e.target.closest('#ip-copy-all');if(all&&window.outpostIpReport)return copyText(formatIpReport(window.outpostIpReport));const one=e.target.closest('[data-ip-copy]');if(one&&window.outpostIpReport){const item=window.outpostIpReport[Number(one.dataset.ipCopy)];if(item)return copyText(item[0]+': '+item[1])}});
$('#ip-history').addEventListener('click',e=>{const b=e.target.closest('[data-ip-history]');if(!b)return;const item=readIpHistory()[Number(b.dataset.ipHistory)];if(item){$('#ip-input').value=item.input;$('#ip-form').requestSubmit()}});
$('#ip-history-clear').onclick=()=>{localStorage.removeItem(ipHistoryKey);renderIpHistory();toast('IP history cleared')};
renderIpHistory();
async function loadFiles(path=''){try{const data=await api('fs/list?path='+encodeURIComponent(path));window.outpostCurrentFolder=data.current;window.outpostParentFolder=data.parent;window.outpostFiles=data.entries;$('#file-breadcrumb').innerHTML=(data.current?'<button id="file-up" class="secondary">← Back</button> <span class="file-current-path">'+esc(data.current)+'</span>':'<span>Selected folders</span>')+'<button id="file-root" class="quiet-button">Root folders</button>'; renderFiles()}catch(e){toast(e.message)}}
function renderFiles(){
 const q=$('#file-filter').value.toLowerCase();
 const files=(window.outpostFiles||[]).filter(f=>f.name.toLowerCase().includes(q));
 window.visibleOutpostFiles=files.slice(0,250);
 $('#file-list').innerHTML=window.visibleOutpostFiles.map((f,i)=>{
  if(f.directory)return '<div class="item file-row"><button class="file-pick" data-action="open" data-index="'+i+'">📁 '+esc(f.name)+'</button><small>Folder</small><div class="action-row"><button class="secondary" data-action="copy" data-index="'+i+'">Copy folder</button><button class="secondary" data-action="move" data-index="'+i+'">Move</button><button class="secondary" data-action="delete" data-index="'+i+'">Delete</button></div></div>';
  const zip=f.name.toLowerCase().endsWith('.zip');
  return '<div class="item file-row"><label><input class="zip-pick" type="checkbox" value="'+i+'"> '+esc(f.name)+'</label><small>'+esc(f.size.toLocaleString())+' bytes</small><div class="action-row"><button class="secondary" data-action="inspect" data-index="'+i+'">Inspect</button><button class="secondary" data-action="download" data-index="'+i+'">Download</button><button class="secondary" data-action="rename" data-index="'+i+'">Rename</button><button class="secondary" data-action="copy" data-index="'+i+'">Copy</button><button class="secondary" data-action="move" data-index="'+i+'">Move</button>'+(zip?'<button class="secondary" data-action="extract" data-index="'+i+'">Extract</button>':'')+'<button class="secondary" data-action="delete" data-index="'+i+'">Delete</button></div></div>';
 }).join('')||'<p class="empty-state">This folder is empty.</p>';
}
$('#file-list').onclick=async e=>{
 const b=e.target.closest('button[data-action]');if(!b)return;
 const f=window.visibleOutpostFiles?.[Number(b.dataset.index)];if(!f)return;
 if(b.dataset.action==='open'){history.pushState({outpostView:'archive',outpostFolder:f.path},'','#archive');return loadFiles(f.path)}
 if(b.dataset.action==='inspect')return window.inspectFile(Number(b.dataset.index));
 if(b.dataset.action==='download')return window.fileDownload(f.path);
 if(b.dataset.action==='rename')return window.fileRename(f.path);
 if(b.dataset.action==='delete')return window.fileDelete(f.path);
 if(b.dataset.action==='copy')return window.fileCopy(f.path);
 if(b.dataset.action==='move')return window.fileMove(f.path);
 if(b.dataset.action==='extract')return window.fileExtract(f.path);
};
window.inspectFile=async i=>{const f=window.visibleOutpostFiles?.[i];if(!f)return;try{const d=await api('file/analyze',{method:'POST',body:JSON.stringify({path:f.path})});$('#file-analysis').classList.remove('empty-state');$('#file-analysis').innerHTML='<div class="item"><div class="section-row"><b>'+esc(d.name)+'</b><button type="button" class="secondary" id="file-analysis-back">← Back to files</button></div><p>'+esc(d.type)+' · '+d.size.toLocaleString()+' bytes</p><small>SHA-256</small><code class="hash">'+esc(d.sha256)+'</code><pre>'+esc(d.preview||'No text preview available.')+'</pre></div>';$('#file-analysis-back').onclick=()=>{$('#file-analysis').textContent='Choose a file from the archive.'}}catch(e){toast(e.message)}};
$('#file-filter').oninput=renderFiles;$('#file-refresh').onclick=loadFiles;$('#file-breadcrumb').onclick=e=>{if(e.target.id==='file-up'){history.back();if(!history.state?.outpostFolder)loadFiles(window.outpostParentFolder||'')}if(e.target.id==='file-root'){history.pushState({outpostView:'archive',outpostFolder:''},'','#archive');loadFiles('')}};

async function fileAction(body){const d=await api('file/action',{method:'POST',body:JSON.stringify(body)});await loadFiles();return d}
$('#folder-create').onclick=async()=>{let parent=window.outpostCurrentFolder;if(!parent)parent=await outpostDialog({title:'Choose destination folder',message:'Enter a configured folder path.',placeholder:'/storage/emulated/0/Documents'});if(!parent)return;const name=await outpostDialog({title:'Create folder',placeholder:'Folder name'});if(!name)return;try{await fileAction({operation:'mkdir',parent,name});toast('Folder created')}catch(e){toast(e.message)}};
$('#file-upload').onclick=async()=>{const f=await outpostFileChooser({title:'Upload to File Archive'});if(!f)return;let parent=window.outpostCurrentFolder;if(!parent)parent=await outpostDialog({title:'Upload destination',message:'Enter a configured folder path.',placeholder:'/storage/emulated/0/Documents'});if(!parent)return;try{const bytes=new Uint8Array(await f.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));const content_base64=btoa(binary);await fileAction({operation:'upload',parent,name:f.name,content_base64});toast('File uploaded locally')}catch(x){toast(x.message)}};
window.fileRename=async path=>{const name=await outpostDialog({title:'Rename file',value:path.split('/').pop(),placeholder:'New file name'});if(!name)return;try{await fileAction({operation:'rename',path,name});toast('Renamed')}catch(e){toast(e.message)}};
window.fileDelete=async path=>{if(!await outpostDialog({title:'Delete file or folder?',message:'Only empty folders can be deleted. This action cannot be undone.',confirmOnly:true,danger:true}))return;try{await fileAction({operation:'delete',path});$('#file-analysis').textContent='Choose a file from the archive.';toast('Deleted locally')}catch(e){toast(e.message)}};
window.fileDownload=path=>{location.href='/api/file/download?path='+encodeURIComponent(path)};

window.fileCopy=async path=>{const name=await outpostDialog({title:'Copy file',value:path.split('/').pop(),placeholder:'Copy name'});if(!name)return;try{await fileAction({operation:'copy',path,parent:window.outpostCurrentFolder,name});toast('Copied locally')}catch(e){toast(e.message)}};
window.fileMove=async path=>{const parent=await outpostDialog({title:'Move file',message:'Enter a configured destination folder path.',placeholder:'/storage/emulated/0/Documents'});if(!parent)return;try{await fileAction({operation:'move',path,parent,name:path.split('/').pop()});toast('Moved locally')}catch(e){toast(e.message)}};
window.fileExtract=async path=>{const name=await outpostDialog({title:'Extract archive',value:path.split('/').pop().replace(/\.zip$/i,''),placeholder:'Destination folder name'});if(name===null)return;try{await fileAction({operation:'extract',path,parent:window.outpostCurrentFolder,name});toast('Archive extracted')}catch(e){toast(e.message)}};
$('#zip-selected').onclick=async()=>{const picks=[...document.querySelectorAll('.zip-pick:checked')].map(x=>window.visibleOutpostFiles[Number(x.value)]).filter(Boolean);if(!picks.length){toast('Select files first');return}const name=await outpostDialog({title:'Create ZIP archive',value:'outpost-archive.zip',placeholder:'Archive name'});if(!name)return;try{await fileAction({operation:'zip',paths:picks.map(x=>x.path),parent:window.outpostCurrentFolder,name});toast('ZIP archive created')}catch(e){toast(e.message)}};
$('#duplicate-scan').onclick=async()=>{const box=$('#duplicate-results');box.textContent='Scanning configured folders locally…';try{const d=await api('duplicates');box.innerHTML='<p>Scanned '+d.files_scanned+' files · '+(d.bytes_scanned/1048576).toFixed(1)+' MB'+(d.limited?' · scan limit reached':'')+'</p>'+(d.groups.map(g=>'<div class="item"><b>'+esc(g.files.length+' identical files')+'</b><small>'+esc(g.size.toLocaleString())+' bytes · SHA-256 '+esc(g.sha256)+'</small>'+g.files.map(p=>'<p>'+esc(p)+'</p>').join('')+'</div>').join('')||'<p class="empty-state">No duplicate files found.</p>')}catch(e){box.textContent=e.message}};

$('#knowledge-import').onclick=async()=>{const f=await outpostFileChooser({title:'Import offline knowledge pack',accept:'.zip,application/zip'});if(!f)return;try{if(f.size>15_000_000)throw Error('ZIP exceeds 15 MB');const bytes=new Uint8Array(await f.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));const d=await api('knowledge/import',{method:'POST',body:JSON.stringify({archive_base64:btoa(binary)})});$('#knowledge-import-status').textContent='Imported '+d.imported+' files · skipped '+d.skipped;toast('Offline knowledge pack imported');await loadOffline();await refresh()}catch(x){$('#knowledge-import-status').textContent=x.message;toast(x.message)}};

async function loadOffline(){try{const [z,m,k,s,c]=await Promise.all([api('zim'),api('modules'),api('knowledge/catalog'),api('system'),api('zim/catalog')]);loadWikiStatus();window.outpostZimArchives=z;window.outpostZimCatalog=c.items||[];$('#zim-catalog').innerHTML='<p class="muted">Choose only the libraries you want. Downloads happen in your browser; OUTPOST never downloads automatically. After downloading, move the .zim file into <code>data/zim/</code> and scan again.</p>'+window.outpostZimCatalog.map(x=>'<div class="item"><b>'+esc(x.title)+'</b><small>'+esc(x.size_label)+' · '+esc(x.file)+'</small><p>'+esc(x.description)+'</p><div class="action-row"><a class="secondary" href="'+esc(x.url)+'" target="_blank" rel="noopener noreferrer">'+(x.id==='official-library'?'Browse official catalogue ↗':'Browse archive directory ↗')+'</a></div></div>').join('');$('#zim-list').innerHTML=z.map((f,i)=>'<div class="item"><b>'+esc(f.name)+'</b><p>'+esc(f.path)+'</p><small>'+(f.size/1073741824).toFixed(2)+' GB · '+new Date(f.modified*1000).toLocaleDateString()+(f.valid_header?' · ZIM '+esc(f.version||''):' · Header not verified')+'</small>'+(s.commands['kiwix-serve']&&f.valid_header?'<div class="action-row"><button class="secondary" data-zim-serve="'+i+'">Open with local Kiwix</button></div>':'')+'</div>').join('')||'<p class="empty-state">No ZIM files found. Add an archive to data/zim or a selected folder.</p>';try{const probe=await fetch('/static/kiwix/www/index.html',{cache:'no-store'});const installed=probe.ok;$('#kiwix-launch').hidden=!installed;$('#kiwix-install-help').hidden=installed;$('#kiwix-install-instructions').hidden=installed;$('#zim-reader-status').textContent=installed?'Bundled Kiwix JS is installed. Open it to select and read any compatible local ZIM archive.':(s.commands['kiwix-serve']?'Local kiwix-serve is available; the bundled full reader can also be installed below.':'Full ZIM reader not installed yet. Run the one-time installer below; after that it works offline.')}catch(e){$('#zim-reader-status').textContent='Could not check bundled Kiwix reader status.'}$('#knowledge-status').innerHTML=m.filter(x=>['grimoire','bughunter','kiwix'].includes(x.id)).map(x=>'<div class="statusline"><span>'+esc(x.name)+'</span><b>'+esc(x.status)+(x.count?' · '+x.count:'')+'</b></div>').join('');window.outpostKnowledgeItems=k;$('#knowledge-catalog').innerHTML=k.map((x,i)=>'<div class="item"><button class="file-pick" data-knowledge-index="'+i+'">'+esc(x.title)+'</button><small>'+esc(x.path)+(x.skill?' · Agent Skill':'')+'</small><p>'+esc(x.description)+'</p></div>').join('')||'<p class="empty-state">No imported knowledge packs yet.</p>'}catch(e){toast(e.message)}}

$('#knowledge-catalog').onclick=e=>{const b=e.target.closest('[data-knowledge-index]');if(b){const x=window.outpostKnowledgeItems?.[Number(b.dataset.knowledgeIndex)];if(x)readKnowledge(x.path)}};
window.readKnowledge=async path=>{try{const d=await api('knowledge/read?path='+encodeURIComponent(path));$('#knowledge-reader').classList.remove('empty-state');$('#knowledge-reader').innerHTML='<div class="item"><b>'+esc(d.name)+'</b><small>'+esc(d.path)+'</small><pre>'+esc(d.content)+'</pre></div>'}catch(e){toast(e.message)}};

$('#zim-refresh').onclick=loadOffline;
$('#kiwix-install-help').onclick=()=>{$('#kiwix-install-instructions').hidden=!$('#kiwix-install-instructions').hidden};
$('#zim-list').onclick=async e=>{const b=e.target.closest('[data-zim-serve]');if(!b)return;const f=window.outpostZimArchives?.[Number(b.dataset.zimServe)];if(!f)return;b.disabled=true;$('#zim-reader-status').textContent='Starting local Kiwix reader…';try{const d=await api('zim/serve',{method:'POST',body:JSON.stringify({path:f.path})});$('#zim-reader-status').innerHTML='Reader ready: <a href="'+esc(d.url)+'" target="_blank" rel="noopener noreferrer">Open '+esc(f.name)+' locally ↗</a>'}catch(x){$('#zim-reader-status').textContent=x.message}finally{b.disabled=false}};
async function loadWikiStatus(){
 const box=$('#wiki-status');
 try{
  const d=await api('wiki/status');
  box.innerHTML='<div class="statusline"><span>Import</span><b>'+(d.running?'Running':d.ready?'Ready':'Not imported')+'</b></div><div class="statusline"><span>Articles saved</span><b>'+Number(d.articles_saved||d.articles||0).toLocaleString()+'</b></div><div class="statusline"><span>Pages processed</span><b>'+Number(d.pages_seen||0).toLocaleString()+'</b></div><div class="statusline"><span>Stored database</span><b>'+(d.size_bytes?(d.size_bytes/1073741824).toFixed(2)+' GiB':'—')+'</b></div>'+(d.source?'<small>'+esc(d.source)+'</small>':'')+(d.error?'<p class="error">'+esc(d.error)+'</p>':'')+(d.running?'<p class="muted">Import is running in the background. Keep the source dump in place and refresh this panel for progress.</p>':'');
 }catch(e){box.textContent=e.message}
}
$('#wiki-import').onclick=async()=>{
 const path=$('#wiki-source').value.trim();
 if(!path){toast('Enter the full path to a local Wikipedia XML dump');return}
 const b=$('#wiki-import');b.disabled=true;
 try{await api('wiki/import',{method:'POST',body:JSON.stringify({path})});toast('Wikipedia import started');await loadWikiStatus()}
 catch(e){toast(e.message)}finally{b.disabled=false}
};
$('#wiki-refresh').onclick=loadWikiStatus;
$('#wiki-images-import').onclick=async()=>{
 const path=$('#wiki-image-pack').value.trim();if(!path){toast('Enter the path to a local image ZIP');return}
 const b=$('#wiki-images-import');b.disabled=true;
 try{const d=await api('wiki/images/import',{method:'POST',body:JSON.stringify({path})});toast('Added '+d.images_added+' curated images');}
 catch(e){toast(e.message)}finally{b.disabled=false}
};

async function runWikiSearch(){
 const q=$('#wiki-q').value.trim();if(!q)return;
 const box=$('#wiki-results');box.textContent='Searching local article index…';
 try{
  const rows=await api('wiki/search?q='+encodeURIComponent(q));
  window.outpostWikiResults=rows;
  box.innerHTML=rows.map(x=>'<div class="item"><button class="file-pick" data-wiki-id="'+x.id+'">'+esc(x.title)+'</button><small>'+Number(x.chars).toLocaleString()+' characters</small><p>'+esc(x.lead.slice(0,420))+'</p></div>').join('')||'<p class="empty-state">No matching articles.</p>';
 }catch(e){box.textContent=e.message}
}
$('#wiki-search').onclick=runWikiSearch;
$('#wiki-q').onkeydown=e=>{if(e.key==='Enter')runWikiSearch()};
$('#wiki-results').onclick=async e=>{
 const b=e.target.closest('[data-wiki-id]');if(!b)return;
 try{
  const d=await api('wiki/article?id='+encodeURIComponent(b.dataset.wikiId));
  const imgs=d.images.length?'<div class="wiki-images">'+d.images.map(name=>'<figure><img loading="lazy" src="/api/wiki/image?name='+encodeURIComponent(name)+'" alt="'+esc(name)+'" onerror="this.closest(\'figure\').remove()"><figcaption>'+esc(name)+'</figcaption></figure>').join('')+'</div>':'';
  $('#wiki-reader').innerHTML='<article class="item"><h3>'+esc(d.title)+'</h3><small>'+Number(d.chars).toLocaleString()+' characters · locally stored</small>'+imgs+'<pre class="wiki-article">'+esc(d.body)+'</pre></article>';
 }catch(x){toast(x.message)}
};
async function loadSecurity(){try{const [m,s]=await Promise.all([api('modules'),api('system')]);$('#module-list').innerHTML=m.map(x=>'<div class="item"><div class="module-top"><b>'+esc(x.name)+'</b><span class="module-status">'+esc(x.status)+'</span></div><p>'+esc(x.role)+'</p><small>'+esc(x.detail)+'</small><small>Offline native module</small></div>').join('');$('#system-info').innerHTML='<div class="statusline"><span>Platform</span><b>'+esc(s.platform)+'</b></div><div class="statusline"><span>Python</span><b>'+esc(s.python)+'</b></div><div class="statusline"><span>Termux</span><b>'+(s.termux?'Detected':'Not detected')+'</b></div><div class="statusline"><span>Architecture</span><b>'+esc(s.machine)+'</b></div>'+(s.disk?'<div class="statusline"><span>Free storage</span><b>'+(s.disk.free/1073741824).toFixed(2)+' GB</b></div>':'')+Object.entries(s.commands).map(x=>'<div class="statusline"><span>'+esc(x[0])+'</span><b>'+(x[1]?'Available':'Not installed')+'</b></div>').join('')}catch(e){toast(e.message)}}

$('#termux-packages').onclick=async()=>{const box=$('#termux-package-list');box.textContent='Reading local package database…';try{const d=await api('termux/packages');box.innerHTML='<p>'+esc(String(d.count||0))+' locally installed packages</p>'+d.packages.map(x=>'<div class="statusline"><span>'+esc(x.name)+'</span><b>'+esc(x.version)+'</b></div>').join('')+(d.truncated?'<p class="muted">List capped at 2,000 entries.</p>':'')}catch(e){box.textContent=e.message}};
$('#security-tool').onchange=()=>{const mode=$('#security-tool').value;const on=mode==='pipeline';$('#pipeline-op').hidden=!on;$('#pipeline-arg').hidden=!(on||mode==='diff');if(mode==='diff')$('#pipeline-arg').placeholder='Paste comparison text here';else $('#pipeline-arg').placeholder='Optional transform argument'};
$('#security-run').onclick=async()=>{const tool=$('#security-tool').value;const text=$('#security-input').value;const path=$('#security-file-path').value.trim();const arg=$('#pipeline-arg').value;const op=$('#pipeline-op').value;const args=op==='replace'?arg.split('|',2):arg?[arg]:[];const output=$('#security-tool-output');const copy=$('#security-copy-output');output.textContent='Running…';copy.disabled=true;try{const d=await api('security/tool',{method:'POST',body:JSON.stringify({tool,text,path,argument:arg,steps:tool==='pipeline'?[{op,args}]:[]})});output.textContent=JSON.stringify(d,null,2);copy.disabled=false}catch(e){output.textContent=e.message;copy.disabled=false}};
$('#security-copy-output').onclick=()=>copyText($('#security-tool-output').textContent);
$('#security-search').onclick=()=>runSearch('#security-q','#security-results');$('#security-q').onkeydown=e=>{if(e.key==='Enter')runSearch('#security-q','#security-results')};

async function uplinkStatus(){const d=await api('uplink/status');$('#uplink-state').innerHTML='<div class="statusline"><span>Indexed documents</span><b>'+d.documents+'</b></div><div class="statusline"><span>Passages</span><b>'+d.chunks+'</b></div><div class="statusline"><span>Feedback records</span><b>'+d.feedback+'</b></div><small>'+esc(d.engine)+' · device-local</small>'}
$('#uplink-status').onclick=()=>uplinkStatus().catch(e=>toast(e.message));
$('#uplink-rebuild').onclick=async()=>{const b=$('#uplink-rebuild');b.disabled=true;$('#uplink-state').textContent='Building bounded passages from the local document index…';try{const d=await api('uplink/rebuild',{method:'POST',body:'{}'});$('#uplink-state').innerHTML='<p>Added '+d.chunks_added+' passages · '+d.chunks_total+' total · '+d.documents_seen+' documents checked</p>';toast('Uplink passage index updated')}catch(e){$('#uplink-state').textContent=e.message}finally{b.disabled=false}};
async function uplinkSearch(){const q=$('#uplink-q').value.trim();if(!q)return;try{const d=await api('uplink/search',{method:'POST',body:JSON.stringify({query:q,limit:12})});window.outpostUplinkResults=d.results;window.outpostUplinkQuery=q;$('#uplink-results').innerHTML=d.results.map(x=>'<div class="item"><b>'+esc(x.title)+'</b><small>'+esc(x.section)+' · '+esc(x.path)+'</small><p>'+esc(x.snippet)+'</p><small>Source citation: '+esc(x.path)+'</small><div class="action-row"><button class="secondary" data-uplink-feedback="1" data-chunk="'+x.id+'">Helpful</button><button class="secondary" data-uplink-feedback="0" data-chunk="'+x.id+'">Not helpful</button></div></div>').join('')||'<p class="empty-state">No matching passages. Build or refresh the passage index first.</p>'}catch(e){$('#uplink-results').textContent=e.message}}
$('#uplink-search').onclick=uplinkSearch;$('#uplink-q').onkeydown=e=>{if(e.key==='Enter')uplinkSearch()};
async function loadUplinkQueue(){const items=await api('uplink/queue');$('#uplink-queue').innerHTML=items.map(x=>'<div class="item"><b>#'+x.id+' · '+esc(x.query)+'</b><small>'+esc(x.status)+' · '+new Date(x.created*1000).toLocaleString()+'</small>'+(x.answer_note?'<p>'+esc(x.answer_note)+'</p>':'')+(x.status==='open'?'<button class="secondary" data-uplink-resolve="'+x.id+'">Mark resolved</button>':'')+'</div>').join('')||'<p class="empty-state">No queued questions.</p>'}
$('#uplink-ask').onclick=async()=>{const query=$('#uplink-q').value.trim();if(!query)return;try{const d=await api('uplink/ask',{method:'POST',body:JSON.stringify({query,limit:12})});window.outpostUplinkResults=d.results;window.outpostUplinkQuery=query;$('#uplink-results').innerHTML=d.results.map(x=>'<div class="item"><b>'+esc(x.title)+'</b><small>'+esc(x.section)+' · '+esc(x.path)+'</small><p>'+esc(x.snippet)+'</p><small>Source citation: '+esc(x.path)+'</small><div class="action-row"><button class="secondary" data-uplink-feedback="1" data-chunk="'+x.id+'">Helpful</button><button class="secondary" data-uplink-feedback="0" data-chunk="'+x.id+'">Not helpful</button></div></div>').join('')||'<p class="empty-state">No matching local passages yet. Your question has been saved to the queue.</p>';await loadUplinkQueue();toast('Question saved to local queue')}catch(e){toast(e.message)}};
$('#uplink-queue-refresh').onclick=()=>loadUplinkQueue().catch(e=>toast(e.message));
$('#uplink-queue').onclick=async e=>{const b=e.target.closest('[data-uplink-resolve]');if(!b)return;const note=await outpostDialog({title:'Resolve question',message:'Add an optional resolution note.',value:'',multiline:true,placeholder:'Resolution details…'});if(note===null)return;try{await api('uplink/resolve',{method:'POST',body:JSON.stringify({id:Number(b.dataset.uplinkResolve),answer_note:note})});await loadUplinkQueue()}catch(x){toast(x.message)}};

$('#uplink-results').onclick=async e=>{const b=e.target.closest('[data-uplink-feedback]');if(!b)return;try{await api('uplink/feedback',{method:'POST',body:JSON.stringify({query:window.outpostUplinkQuery||$('#uplink-q').value,chunk_id:Number(b.dataset.chunk),helpful:b.dataset.uplinkFeedback==='1'})});b.parentElement.innerHTML='<small>Feedback saved locally.</small>'}catch(x){toast(x.message)}};
$('#uplink-evaluate').onclick=async()=>{try{const d=await api('uplink/evaluate',{method:'POST',body:JSON.stringify({query:$('#uplink-eval-query').value,expected_path:$('#uplink-eval-source').value,limit:10})});$('#uplink-eval-result').innerHTML='<div class="item"><b>Expected source '+(d.matched?'found':'not found')+'</b><p>Reciprocal rank: '+d.reciprocal_rank+'</p>'+d.results.map(x=>'<small>'+esc(x.path)+' · '+esc(x.title)+'</small>').join('<br>')+'</div>'}catch(e){$('#uplink-eval-result').textContent=e.message}};
async function buildUplinkReport(){const d=await api('uplink/report');window.outpostUplinkReport=d;$('#uplink-report-view').innerHTML='<div class="item"><b>Local retrieval report</b><p>'+d.documents+' documents · '+d.passages+' passages</p><p>'+d.feedback_count+' feedback records · '+d.helpful_count+' helpful</p><p>'+d.evaluation_runs+' evaluation runs · '+d.evaluation_hits+' hits · MRR '+Number(d.mean_reciprocal_rank).toFixed(3)+'</p><p>'+d.questions_open+' open questions · '+d.questions_total+' total</p><b>Top indexed sources</b>'+d.top_sources.map(x=>'<small>'+esc(x.path)+' · '+x.passages+' passages</small>').join('')+'</div>';return d}
$('#uplink-report').onclick=()=>buildUplinkReport().catch(e=>toast(e.message));
$('#uplink-report-export').onclick=async()=>{try{const d=window.outpostUplinkReport||await buildUplinkReport();const a=document.createElement('a');const u=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));a.href=u;a.download='outpost-uplink-report.json';a.click();URL.revokeObjectURL(u)}catch(e){toast(e.message)}};
$('#uplink-report-html').onclick=async()=>{try{const d=window.outpostUplinkReport||await buildUplinkReport();const escHtml=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const sources=d.top_sources.map(x=>'<tr><td>'+escHtml(x.path)+'</td><td>'+x.passages+'</td></tr>').join('');const page='<!doctype html><html><meta charset="utf-8"><title>OUTPOST Uplink report</title><style>body{font:16px system-ui;max-width:900px;margin:40px auto;padding:0 20px;color:#202820}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid #ccc;padding:8px;text-align:left}</style><h1>OUTPOST Uplink report</h1><p>Generated '+new Date(d.generated*1000).toLocaleString()+'</p><h2>Index</h2><p>'+d.documents+' documents · '+d.passages+' passages</p><h2>Feedback</h2><p>'+d.feedback_count+' records · '+d.helpful_count+' helpful</p><h2>Evaluation</h2><p>'+d.evaluation_runs+' runs · '+d.evaluation_hits+' hits · MRR '+Number(d.mean_reciprocal_rank).toFixed(3)+'</p><h2>Ask queue</h2><p>'+d.questions_open+' open / '+d.questions_total+' total</p><h2>Top sources</h2><table><tr><th>Path</th><th>Passages</th></tr>'+sources+'</table></html>';const a=document.createElement('a');const u=URL.createObjectURL(new Blob([page],{type:'text/html'}));a.href=u;a.download='outpost-uplink-report.html';a.click();URL.revokeObjectURL(u)}catch(e){toast(e.message)}};
$('#bughunter-open').onclick=async()=>{try{const d=await api('knowledge/read?path='+encodeURIComponent('bughunter/OUTPOST_OFFLINE_PLAYBOOKS.md'));$('#bughunter-reader').classList.remove('empty-state');$('#bughunter-reader').innerHTML='<div class="item"><b>'+esc(d.name)+'</b><pre>'+esc(d.content)+'</pre></div>'}catch(e){toast(e.message)}};
$('#termux-toolbox').onclick=async()=>{try{const d=await api('termux/toolbox');$('#termux-toolbox-list').innerHTML=d.tools.map(x=>'<div class="item"><b>'+esc(x.name)+'</b><p>'+esc(x.purpose)+'</p><small>'+esc(x.usage)+'</small><small>'+esc(x.mode)+' · '+(d.available[x.name]?'installed':'not found')+'</small></div>').join('')}catch(e){toast(e.message)}};
window.addEventListener('popstate',e=>{const state=e.state||{};if(state.outpostFolder!==undefined){loadFiles(state.outpostFolder);return}view(location.hash.slice(1)||'overview',false)});
view(location.hash.slice(1)||'overview',false);


// Landing navigation and local visual preferences.
(()=>{
 const landing=document.getElementById('landing'),shell=document.querySelector('.app-shell');
 const enter=(target='overview')=>{landing.hidden=true;shell.classList.remove('app-hidden');if(typeof view==='function')view(target);window.scrollTo(0,0)};
 document.getElementById('landing-start').addEventListener('click',()=>enter('overview'));
 document.getElementById('landing-settings').addEventListener('click',()=>enter('settings'));
 document.getElementById('landing-leave').addEventListener('click',()=>{document.querySelector('.landing-menu').innerHTML='<div class="landing-kicker">SESSION CLOSED</div><h2 style="color:#fff">OUTPOST is standing by.</h2><p class="muted">You can close this tab. Your local data remains on this device.</p><button class="landing-choice" id="landing-return">RETURN <span>↗</span></button>';document.getElementById('landing-return').onclick=()=>location.reload()});
 const ids=['pref-glow','pref-scale','pref-motion','pref-audio','pref-alert','pref-fullglow','pref-compact','pref-effects','pref-audio-on'];
 const defaults={'pref-glow':'65','pref-scale':'100','pref-motion':'55','pref-audio':'70','pref-alert':'45','pref-fullglow':true,'pref-compact':false,'pref-effects':true,'pref-audio-on':false};
 const apply=()=>{const get=id=>localStorage.getItem('outpost-'+id);document.body.classList.toggle('low-glow',get('pref-fullglow')==='false'||get('pref-glow')==='0');document.body.classList.toggle('compact-ui',get('pref-compact')==='true');document.body.classList.toggle('no-motion',get('pref-effects')==='false'||get('pref-motion')==='0');document.documentElement.style.setProperty('--ui-scale',(Number(get('pref-scale')||100)/100).toFixed(2));};
 ids.forEach(id=>{const el=document.getElementById(id);if(!el)return;const saved=localStorage.getItem('outpost-'+id);if(saved!==null){if(el.type==='checkbox')el.checked=saved==='true';else el.value=saved}else{if(el.type==='checkbox')el.checked=defaults[id];else el.value=defaults[id]}el.addEventListener('input',()=>{localStorage.setItem('outpost-'+id,el.type==='checkbox'?String(el.checked):el.value);apply()})});
 document.getElementById('settings-reset-visual')?.addEventListener('click',()=>{ids.forEach(id=>localStorage.removeItem('outpost-'+id));ids.forEach(id=>{const el=document.getElementById(id);if(!el)return;el.type==='checkbox'?el.checked=defaults[id]:el.value=defaults[id]});apply()});apply();
})();
